// Cm JS FFIテスト用のローカルfixtureパッケージ（npm installなしでNODE_PATH経由で解決される）
exports.scale = function (point, factor) {
    return { x: point.x * factor, y: point.y * factor };
};
exports.describe = function (point) {
    return "(" + point.x + "," + point.y + ")";
};
exports.applyTwice = function (fn, v) {
    return fn(fn(v));
};
exports.makeGreeter = function (name) {
    return {
        name: name,
        greet: function (msg) { return msg + ", " + this.name + "!"; },
    };
};
